cd /tmp/dec; python3 - <<'E'
import re,os,collections
c=collections.Counter();ex={}
for f in sorted(os.listdir('.')):
    dep=f.split('-')[0]
    if dep in('central','north','south'):continue
    for l in open(f,newline='').read().split('\n'):
        for tok in re.split(r'[,;|\t]',l):
            s=re.sub(r'\d','9',tok)
            if re.fullmatch(r'[\d\-:T+Z./ ]{5,}',tok):
                c[(dep,s)]+=1; ex.setdefault((dep,s),(f,tok))
for k,v in sorted(c.items()): print(k,v,ex[k])
E

